) AS (
  VALUES 
    (112::BIGINT, 'El curso es aburrido y él lo sabe, entonces lo hace más llevadero, se pasa haciendo los trabajos. Le gusta que la gente participe y en general, el curso es fácil y el profe cae bastante bien. Para comunicarse con él es medio difícil, todo es por medio de la asistente.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '87d655ddaff288bfb5b7f63ee252e8ff51331a22e7cdef64a844dc441c965999'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Increíble profe, clases entretenidas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-03-10T00:00:00+00:00'::TIMESTAMPTZ, '04f7e6a670ce2691a08050beb6e32e95a843ec93a348b0bdf777b4fe3284d0f1'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'El curso es un bostezo, tiene que hacer un cuaderno que debe entregar al final del curso con todo lo que se vio. Hay una presentación en grupo, y como 3 trabajos grupales. Curso aburrido, hay mejores opciones para pasar sin hacer nada, pero igual para con buena nota con él.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '7d9b60dded7c153a54d676902a8cb898219f3f9f0b554408d5a78e82819df50b'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Sabe que su clase no es de suma importancia por lo que se pasa fácil; Una presentación en grupos de 6 de alrededor de unos 40 minutos y el resto trabajos súper fáciles. Con que presente decentemente pasa el curso y eso es todo. No se va a arrepentir si matricula con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, '986a5bc2c924d0cd0780443be1dd6f3de763c5e8599bbe7d01df46e31a8afd5b'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Es un súper profe, entiende que su materia no aporta mucho pero busca que aprendas algo, por lo que apenas y deja trabajos y son súper fáciles, muy buena gente y conecta muy bien con los estudiantes. En todo sentido es un profe increíble y volvería a llevar con él sin dudarlo'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-03T00:00:00+00:00'::TIMESTAMPTZ, '5d6e952fe1905ee2c8b79b449aee0c57abb80257eb6b82eedc6150eb95f99fe0'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Me encantó este profe, clases cortas, trabajos grupales, le gusta que los estudiantes participen, pero no se les obliga a participar de la clase. Definitivamente llevaría con el cualquier otro curso,'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2025-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'c74bb2b913856c5c384faf9e9e0a8785a75bc4219905d5d46b47886a6b93907c'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, '9d7008584f35e4495e450083c06204f73c92fbf78993650054db02884edf8f9e'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Es bueno y el curso es bastante fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ac0724d4b57baca56464877a72c7ed142e4e82e2dcf1c3a95d660dd2618a0f64'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Muy facil con este profe, con que vaya a clase y participe se pasa facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'd539940cc3b46ee09e577c1639819963772cef9d4c22b72c028c59917dcb9a54'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Buen Profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'b957aa6c2224619b7076573540e3ed6ab352c16cdf4617e68befa9b34e06cb8d'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-06T00:00:00+00:00'::TIMESTAMPTZ, '93b7ab29452f5ed08f41cfff34bfb91ffee06813d09d743f0fb17e94d51d28c0'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Es una clase relax, y el mae lo sabe, siga las indicaciones, entregue todo a tiempo y ponga en cada trabajo el nombre de los integrantes, son 2 quices grupales, una presentación larga y un examen, todas demasiado fáciles, cumpla con todo y pasa Intro al bosteza.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2024-09-09T00:00:00+00:00'::TIMESTAMPTZ, '04ba6937c9382b5aa39b63e983e665ccc4f8dc14331751070eb12cc9bc0328e1'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Es un buen profe, el problema es la materia en sí, pero solo siga indicaciones y pasa fácil con 10. Él sabe que la clase no interesa, entonces intenta hacerlo interesante y no pesado para los alumnos. Aparte, es una persona muy interesante y pura vida.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2024-08-09T00:00:00+00:00'::TIMESTAMPTZ, '61e7757f62fc024583e879b6b1d888d1da86866a8a14b9630770ba670f540a49'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'El mejor profe para llevar intro al bostezo, los trabajos son muy sencillos, no hace quices y el examen final es facilisimo. 10/10. RECOMENDADO'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'fe0c387f194abbcbaa4273532ea1c27a26d9c84730d9eee18fdf7ebdda080bdc'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Es de los cursos más sencillos, 20% asistencia, 10% una memoria que es de llevar una bitácora de cada clase, 30% una exposición de un caso y 40% trabajos que se hacen durante la clase. Son largos los trabajos, NO graba las clases, tarda en subir las instrucciones y NO contesta rápido.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'a7b81b176f8ecc5e94f84452be863ba52d6c6e1a3373ebb239c3a1151e5bb465'::TEXT, ARRAY[981]::BIGINT[]),
    (112::BIGINT, 'El profe sabe que el curso realmente a los estudiantes no les agrada mucho, por lo que sus clases realmente terminan siendo un tipo conversatorio, las evaluaciones suelen ser sencillas y se hacen en clase y la clase termina siendo interesante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'e7e7d84eb84a4081042b002bba302b7e94dc00c8a7e43aa59ddc51918d4c3079'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'El profesor es buena nota, sabe bien que el curso es una pérdida de tiempo, pero logra convertir el curso en algo muy interesante. No hace quices y el examen final fue muy sencillo, literalmente un "explique" con sus propias palabras. Muuy dinámico y sus "chistes" valen la pena. Lo recomiendo 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'e4fad80ab5ef5bb3dbf68ba5326bb8cc97a666d02885f7ed51e80857dbaf7215'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Buen profe, las clases no se hacen tan pesadas con él, hay que hacer pocos trabajos para pasar, aunque a veces si son algo largos o pesados. Pero se aprueba facil.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2024-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'bf70fc80b20a23cde6d9029150241160fb4a353243eb258a95f56e2dfde577a0'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, '66170be75a750c31ed9e9f3c05eb6f7b5401db3c4d85b4caf6a0e1a6e9371521'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Hace las clases como de hora y media, sabe que su curso es secundario, pero hace las clases super interesantes, no dude en matricular con él. En todo el curso solo tiene que hacer unos trabajillos como entre 5 mentes, dos exposiciones y un resumen de todo lo que habló durante el curso ez ez'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Inspirador']::TEXT[], '2023-12-13T00:00:00+00:00'::TIMESTAMPTZ, '268f4eddbd03c5a77afc93f5101db211743f30b26ea19ad68f7c156938d5641f'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'No deja exámenes, pero sí trabajos en grupo, sin embargo, son muy sencillos. Cuando explica se nota que sabe mucho de lo que habla, y conecta todo con coherencia. Es consiente de que hay cursos más pesados, por lo que trata que su curso sea muy secundario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '04af2c4564376722e263d95c9bbfa435158cae7e998c5bc330c9045b222191b9'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-28T00:00:00+00:00'::TIMESTAMPTZ, '6e8ce2adbf00f2f2d36e144cdf87d282bfbdd6f42d66ba7b89aa1b9777c7bd12'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'El profesor daba clases bastante cortas y divertidas, había bastante participación de la gente y el curso fue sencillo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '42e2d1f0890cfca2186f4c6e428aa88d0d5580a73a1d0a832cbeaa8bdbd02448'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'El profesor logra hacer la clase interesante y divertida. Los trabajos no son difíciles y sí van al grano de lo que se debe aprender, lo cual hace que no sean pesados (lo dice alguien algo perezosa). Hace que en la clase no se tenga miedo a participar. Elija bien a sus compañeros de grupo!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f0f6aa3d23e3d97cf529e5f75f779ae86b3600909aba78c95577e5a10a3ba2d4'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Es un muy buen profesor, sus explicaciones son claras y sencillas. Totalmente recomendado, pero tome en cuenta que deja bastantes trabajos en grupos aleatorios (la mayoría, en realidad) y cuesta comunicarse con él, ya que solo da el Classroom o el correo, que a veces tarda en responder.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '31a19a2d29b67db93e32120bcf8603bf81cc2df4b261df3863c30b72d19211f0'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Es todo pura vida, muy chill con sus clases, comprensivo, le gusta que los estudiantes participen, deja varios analisis de películas (4) que son cortos pero tediosos porque es en grupo. Concuerdo con el comentario anterior jaja el profe esta guapo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Brinda apoyo']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'a51cbdc47e6be53a26ee427c1828508f0c022e3063502e38e8ee2e14ff4d0fac'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'El profe sabe que a nadie le interesa su clase, entonces trata de que el curso no sea tan pesado y le da mucha importancia a las redacciones, más que a la filosofía. Sus clases duraban 1 hora, casi siempre había trabajo en clase, pero eran sencillos. Pd. El profe es muy guapo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '3a2b5bb58ecdc22f16811f1968ccaa1671ef2d3034889c399763106daef9ce7f'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'En general es fácil, deja muchos trabajos en grupos aleatorios. El único aspecto negativo es la dificultad para comunicarse, casi no responder correos y no da otros medios.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2022-05-31T00:00:00+00:00'::TIMESTAMPTZ, '81346e26e82a2d94a4ec901386bb61a6b669dc0294fd998b35d40ba49d823dcd'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Excelente profe. Explica de forma muy clara y concisa, con un tono y ritmo bastante fáciles de comprender. Sus trabajos son en grupos aleatorios, pero no son trabajos complejos ni cuanto menos. Sus examenes son muy fáciles, y deja varias lecturas a lo largo del curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2022-05-09T00:00:00+00:00'::TIMESTAMPTZ, '01b927ef4cda85634585fd5824852ad426e8052335d0b3a02018ec92669779ce'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'f17534b9e2e184ecbe71b2381b3625434ea9a5579439af3caa9a594181de3862'::TEXT, ARRAY[981]::BIGINT[]),
    (112::BIGINT, 'Casi todo el curso era en grupos que él hacía e iba mezclando. En general muy buen profe y vuelve el curso interesante. Las lecturas no suelen ser muy largas y algunas son bastante interesantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '9441e166c6b9f62c9d68c0a1c83aa0dd6cb77383e85d58b73f64b73f9de1fe5f'::TEXT, ARRAY[981]::BIGINT[]),
    (112::BIGINT, 'Muy buen profe, ayuda bastante al estudiante y la clase es interesante, aunque un poco repetitiva la materia en general. Busque buenos compañeros desde un inicio.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'cf52a01c3c53154fa5d1926491ff850e4dc48efa50be5ee6fdf0d058828cc11b'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'El profe es muy pura vida y se nota que le gusta hablar de ética. Las clases duran poco, no más de una hora y las presentaciones son claras. Es un poco desorganizado con las fechas y se enreda solo, pero luego se acomoda mejor.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, '196f1650e3eb5b4cacad74a0882079708046e29a03312ff372814bee1a7d655d'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Excelente profesor, es un pacho, las clases son sumamente interesantes y las evaluaciones de las lecturas no son para nada específicas, un profesor sumamente interesado en su materia y comprensivo con el estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2021-07-25T00:00:00+00:00'::TIMESTAMPTZ, 'b2ff3e26ce145e658cfd7d4c93653e9e311d95d076753ae0f111676241f1e864'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'ES UNA TEJA DE PROFE EN TODO EL SENTIDO DE LA PALABRA....Y ES SUPER COMPRENSIVO.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2021-07-24T00:00:00+00:00'::TIMESTAMPTZ, '59d1ec37b9e740fd6c69528771e483ad2bccb4944d9b8f553f7ae058a08226ac'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Con que le dedique un poquito de tiempo al curso va a pasar fijo! El profe es demasiado buena nota y las clases son cortas para comentar alguna lectura o asi (por cierto nada difíciles)... Matricule sin miedo!'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '7336d23a0fc803ffca2f69abc4e61e7a90731db7d3d06a2c47c199a65e62be51'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Muy buena nota. Si le gusta la materia, las clases se sienten como charlas interesantes. Hay que tomarse el tiempo de saber cómo aplicar APA ya que el profe lo considera un montón para los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, '8a8a8e3ee2ba5f11a42afa57da3ead705b76c2de361ac5244edfa3ea33b0d4ba'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Aburrido como cualquier otro seminario, pero fácil'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0979a5d30a0437da990b02428ceef0aa155b4ec04a6b5ac9301e17d2445d7803'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'El profe explica súper bien, es una eminencia en su campo (filosofía). Comparados a otros profes de intro, él es el mejor. Deja pocas lecturas que son evaluadas o con ensayos o con quices en media clase. Para los ensayos es necesario saber APA, no sean vagxs e investiguen sobre eso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '17ff8fc4690c7c9d1f31eb3304197dc12321040ff22adc232c65b1054f26847b'::TEXT, ARRAY[559]::BIGINT[]),
    (112::BIGINT, 'Es un curso de 2 créditos que lo hace sentir como de 4...'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2021-05-12T00:00:00+00:00'::TIMESTAMPTZ, '10b4af4ea72f0c3d6603f68da2f3a18116ca60dc59ecd9450d08261e60ffc3d4'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Buen profe. Se aprende lo suficiente. Curso muy fácil. Lo llevé en la noche, deja salir muy temprano. Recomendado para este tipo de curso que no importa tanto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'a65689a454be16b00d394fb381d2f2a98745ec451d912f3145ebbc706bf6205f'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a92bf9a6a37aefb0444cb0ec26c36b4d3673fd2f9af26b7baac597da2b631a4a'::TEXT, ARRAY[981]::BIGINT[]),
    (112::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '501d43acf031f867b91952117e91dec081d3aabd03f4aadd42dd4654b75de276'::TEXT, ARRAY[981]::BIGINT[]),
    (112::BIGINT, 'Demasiado buena nota, clases relax, evaluaciones faciles, hace que el curso no se vuelva pesado ni quite mucho tiempo, el curso se vuelve bastante facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'f79cbbb4d738026e94c3745dce777dff7325d3a8ec178aeb9b98cc1fae509b78'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, '896a1b22d5cbc69db3e02d9d344deb511970b8fd72258f52575da15d066eeeae'::TEXT, ARRAY[981]::BIGINT[]),
    (112::BIGINT, 'Es buen profe, el sabe que el curso para uno no es muy importante, por lo que no deja muchas lecturas, es cómico y hace la clase entretenida para que no se duerman.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '49a3ca515b7684c604e26ae72056b86ded5ccf5a7cbcee95cf2b70b944640d21'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Lo recomiendo bastante, se aprende mucho en el curso y las clases son muy entretenidas. No deja muchas lecturas y califica normal.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, '63b35e0ed60efa998b134a24198480ab93a1f91daf57b004ec1431e07b02d61f'::TEXT, ARRAY[980]::BIGINT[]),
    (112::BIGINT, 'Un profe llevadero, a pesar de ser nuevo. No pone fechas límite para los trabajos, pocas lecturas, se aprende y con él se puede pasar hasta con cien.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'a4f49048fd829160532334e27db91591f7be21336d866fe34c61743ec8dc84c9'::TEXT, ARRAY[980]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
